for k in updates:
 updates[k]=updates[k].replace('For AUC, unrounded thresholds give gain at $0<\\delta\\leq0.00428373554$, inconclusive at $0.00428373554<\\delta<0.00550900835$, and equivalent at $\\delta\\geq0.00550900835$. We retain $\\delta=0.005$.',r'For team-axis AUC, let $t$ be the unrounded estimate ($\approx0.004284$) and $u$ its upper 90\% limit ($\approx0.005509$). Gain holds at $0<\delta\leq t$, inconclusive at $t<\delta<u$, and equivalent at $\delta\geq u$. We retain $\delta=0.005$.')
 updates[k]=updates[k].replace('0.0033/0.0028 in Erangel/Taego','0.0033/0.0028 in Erangel and Taego').replace('overall-AUC/rank-correlation thresholds','overall AUC and rank thresholds')
 updates[k]=updates[k].replace(r'}\nWe define','}\nWe define').replace(r'}\nThe source','}\nThe source')

ops=[dict(op='replace_block',block_id=k,old_hash=hashes[k],new_text=v,roadmap_item_ids=sorted(set(ids[k]))) for k,v in updates.items()]
(P/'revision/patch.json').write_text(json.dumps(dict(patch_format_version='1.0',revision_round=1,base_draft_hash=manifest['base_draft_hash'],ops=ops,emitted_by='inline_revision'),ensure_ascii=False,indent=2)+'\n')
print('Changed blocks',len(ops),'/',len(blocks),'abstract words',len(new.split()))
# Regenerate the requested decision table directly from final analysis, without rerunning inference.
rows=[r for r in csv.DictReader((B/'primary_results_v2/contrasts_pooled.csv').open()) if r['kind']=='primary']
labels={'P1':'Phase axis, AUC','P2':'Team axis, AUC','P3':r'Team axis, rank $\\rho$','P4':'Relation alignment, AUC','P5':'Zone token, AUC'}
lines=[r'\begin{table}[t]',r'\centering\footnotesize',r'\caption{Five primary structure decisions: random-effects estimates over 11 cohorts.}',r'\label{tab:primary}',r'\setlength{\tabcolsep}{2.5pt}',r'\begin{tabular}{lrrl}',r'\toprule',r'Comparison & Estimate & 90\% CI & Decision \\',r'\midrule']
for r in rows:
 fmt=lambda x:f'{float(x):+.4f}'
 label=labels[r['primary_id']].replace('\\\\rho','\\rho')
 lines.append(f"{label} & {fmt(r['theta'])} & [{fmt(r['ci90_low'])}, {fmt(r['ci90_high'])}] & "+('Equiv.' if r['verdict']=='equivalent' else 'Inconcl.')+r' \\')
lines += [r'\bottomrule',r'\end{tabular}',r'\smallskip',r'\parbox{\columnwidth}{\scriptsize Bounds are $\pm0.005$ for AUC and $\pm0.01$ for rank correlation. Holm-adjusted one-sided $p$ against zero, in row order: 0.965, $2.22\times10^{-8}$, 0.0122, 0.00259, 0.00924. Equivalence uses unadjusted 90\% intervals.}',r'\end{table}']
